-- Bloque 3: Pastas y Salsas (13 registros).
-- Registros inactivos para validar en Preview sin exponerlos en producción.
-- Preview lee fichas inactivas; producción sigue filtrando activo=true.
begin;
on conflict (plato_id) do update set
  sinonimos = excluded.sinonimos,
  resumen = excluded.resumen,
  hack = excluded.hack,
  que_observar = excluded.que_observar,
  updated_at = now();
commit;
