insert into public.preview_catalogo_maestro_platos
  (plato_id, sinonimos, resumen, hack, que_observar, activo)
values
  ('ravioles', ARRAY['ravioles', 'raviol', 'porcion de ravioles', 'ravioles de carne o verdura']::text[], 'Pasta rellena tradicional. Combina la densidad energética de la masa con un interior proteico o vegetal, resultando en un plato de alta contundencia y saciedad rápida.', 'Evitá sarpullir el plato con exceso de aceite o crema; una cucharada generosa de aceite de oliva crudo y queso de calidad al servir potencian el sabor sin volverse un yunque estomacal. Tip extra: si podés elegir, prioriza rellenos vegetales o de carnes magras, y combinalos masticando lento para amortiguar el pico de almidón.', 'Registra la velocidad con la que aparece el letargo post-almuerzo; al ser una masa elaborada, el tiempo de digestión gástrica suele ser más largo.', false),
  ('sorrentinos', ARRAY['sorrentinos', 'sorrentino', 'porcion de sorrentinos']::text[], 'Pasta rellena de mayor tamaño y presencia, con una estructura de masa y un relleno denso (jamón, queso, ricota o zapallo) que aporta una carga calórica considerable.', 'Al ser porciones contundentes, moderá la cantidad total en el plato y acompáñala siempre con un buen vaso de agua o una entrada de hojas verdes para modular la glucemia. Tip extra: una pizca de pimienta negra rallada arriba ayuda a estimular las secreciones biliares para procesar mejor la combinación de lácteos y harinas.', 'Compara tu sensación de comodidad digestiva a las dos horas de haber comido; nota si te genera pesadez o si te mantiene saciado de forma estable.', false),
  ('capeletis', ARRAY['capeletis', 'capeleti', 'cinturitas', 'tortellini']::text[], 'Pasta rellena en formato pequeño, ideal para caldos o salsas ligeras. Aporta carbohidratos de asimilación rápida y un núcleo proteico concentrado.', 'Si los preparás en sopa o caldo liviano, el plato gana una hidratación fantástica que mejora el volumen gástrico sin abusar de grasas pesadas. Tip extra: un toque de queso rallado fino es suficiente para dar perfil de sabor sin saturar la digestión.', 'Presta atención al confort estomacal; al consumirse muchas veces con caldos o salsas simples, suelen digerirse mejor que las pastas grandes pesadas.', false),
  ('lasagna', ARRAY['lasagna', 'lasaña', 'pastel de capas de pasta']::text[], 'Un plato complejo de capas múltiples que intercala masa, carnes, vegetales y abundantes quesos fundidos o salsa blanca. Densidad calórica y proteica muy alta.', 'Por su estructura, funciona como un plato único ultra completo. Evitá sumarle pan u otros acompañamientos pesados al costado. Tip extra: recalentada al día siguiente suele asimilarse un poco mejor porque parte de sus almidones se estabilizan, pero cuida la porción si buscás ligereza.', 'Evalúa la estabilidad de tu energía durante la tarde; al tener una mezcla densa de grasas y harinas, requiere un tiempo de reposo metabólico mayor.', false),
  ('canelones-carne', ARRAY['canelones de carne', 'canelon de carne', 'pionono de carne relleno']::text[], 'Masa enrollada que encierra un relleno proteico de carne vacuna. Buena fuente de aminoácidos combinados con carbohidratos refinados.', 'Cuidado con los excesos de salsa blanca industrial o gratinados hiper-grasos por encima; optar por una salsa de tomate natural ligera cambia por completo la ecuación digestiva. Tip extra: un toque de provenzal en el relleno levanta el sabor y facilita la digestión de las carnes rojas.', 'Nota la saciedad proteica y si sentís la panza estirada o cómoda tras finalizar la porción.', false),
  ('canelones-pollo', ARRAY['canelones de pollo', 'canelon de pollo', 'pasta rellena de pollo']::text[], 'Variante más ligera en cuanto al tipo de proteína. El pollo aporta una carga de aminoácidos nobles con menor densidad grasa que la carne roja.', 'Acompañalos con una salsa sutil o un toque de tomate natural para no tapar la liviandad natural de la carne blanca. Tip extra: una pizca de orégano seco ayuda a realzar el perfil aromático sin pesadez gástrica.', 'Compara la ligereza de esta opción frente a los canelones de carne; vas a notar una transición estomacal mucho más ágil.', false),
  ('canelones-verdura', ARRAY['canelones de verdura', 'canelon de verdura', 'canelones de acelga o espinaca']::text[], 'Masa de pasta estructurada con un corazón de vegetales de hoja (acelga o espinaca) y ricota. Aporte extra de fibra y micronutrientes.', 'Escurrí muy bien el relleno de verdura antes de armarlos para evitar que larguen exceso de agua y arruinen la textura de la masa. Tip extra: un toque de nuez moscada y queso magro realza el sabor de la verdura sin sumar grasas pesadas.', 'Analiza tu tránsito y comodidad abdominal; la fibra de la verdura combinada con la pasta genera una saciedad interesante si la porción es equilibrada.', false),
  ('canelones-choclo', ARRAY['canelones de choclo', 'canelon de choclo', 'humita en masa']::text[], 'Relleno a base de maíz tierno, que aporta un perfil de carbohidratos más dulce, con notas de fibra y azúcares propios del grano.', 'Al tener una base de choclo (carbohidrato dulce), trata de evitar salsas pesadas o azucaradas; un toque de queso fundido salado equilibra perfecto el perfil de sabor. Tip extra: una pizca de pimienta de cayena o pimentón ahumado corta el dulzor y le da carácter al plato.', 'Registra la velocidad de digestión; el choclo tiende a dar una energía rápida que requiere actividad posterior para metabolizarse bien.', false),
  ('salsa-carne-vacuna', ARRAY['salsa carne vacuna', 'boloñesa', 'salsa bolognesa', 'salsa de carne', 'tuco con carne']::text[], 'La clásica salsa robusta a base de tomate y carne picada. Aporta proteínas, sabor umami profundo y una carga energética ideal para combinar con pastas secas o rellenas.', 'Asegurate de cocinarla a fuego lento para que el tomate descarte su acidez natural sin necesidad de agregarle azúcar refinada. Tip extra: un chorrito de vino tinto durante la reducción aporta antioxidantes y un perfil de sabor increíble que eleva cualquier plato simple.', 'Nota cómo complementa a la pasta; una buena boloñesa equilibra la balanza proteica de un plato de harinas.', false),
  ('salsa-pollo', ARRAY['salsa con pollo', 'salsa de pollo', 'tuco de pollo', 'estofado de pollo para pasta']::text[], 'Preparación en base a trozos de pollo estofados en salsa de tomate o caldo. Una alternativa proteica magra y reconfortante.', 'Desmenuzar el pollo dentro de la salsa permite que cada bocado de pasta vaya acompañado de proteína de alta calidad sin pesadez. Tip extra: un toque de laurel y zanahoria rallada en la cocción de la salsa aporta dulzor natural y compuestos protectores digestivos.', 'Evalúa la saciedad liviana que te deja; es una opción excelente para almorzar sin sentir modorra mental posterior.', false),
  ('salsa-mixta', ARRAY['salsa mixta', 'salsa blanca y roja', 'tuco con salsa blanca', 'rosa']::text[], 'Fusión de bechamel (cremosa y untuosa) con salsa de tomate (ácida y fresca). Aporta textura aterciopelada y un alto nivel de palatabilidad.', 'Al ser una salsa densa por la combinación de lácteos y harinas de la blanca, modera la cantidad total en el plato para evitar un vaciado gástrico muy lento. Tip extra: un toque de pimienta negra ayuda a equilibrar la pesadez de la crema y la manteca.', 'Presta atención a la saciedad y a la sed posterior; las salsas con base láctea suelen requerir un buen aporte de agua para procesarse correctamente.', false),
  ('salsa-crema', ARRAY['a la crema', 'salsa crema', 'crema de leche', 'pasta con crema']::text[], 'Untuosidad pura a base de crema de leche reducida. Alto contenido de grasas saturadas lácteas que envuelven la pasta y otorgan un placer gustativo inmediato.', 'Rebajar la crema con un toque del agua de cocción de la pasta (rica en almidón) ayuda a emulsionar mejor la salsa sin usar tanta cantidad de lácteo graso. Tip extra: un golpe de nuez moscada y queso parmesano fresco transforma una crema simple en un manjar digestivamente más amigable.', 'Registra la densidad de la energía posterior; la crema frena fuerte la velocidad de la digestión, generando saciedad muy prolongada pero con riesgo de letargo si la porción es grande.', false),
  ('salsa-verdeo', ARRAY['al verdeo', 'salsa al verdeo', 'cebolla de verdeo con crema']::text[], 'Salsa aromática a base de cebollita de verdeo rehogada (habitualmente con un toque de crema o caldo). Aporta frescura verde y compuestos sulfurados bioactivos de la familia de la cebolla.', 'Rehogá el verdeo a fuego moderado con un hilo de aceite de oliva antes de sumarle la crema; los compuestos de la cebolla protegen la función hepática y suavizan las grasas pesadas. Tip extra: un toque de ralladura de limón al finalizar la cocción le da un giro de frescura descomunal.', 'Nota el confort digestivo; a diferencia de una crema sola, los compuestos aromáticos del verdeo estimulan mejor los jugos gástricos.', false)
